<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\Meeting; use App\Models\MeetingActionItem; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class MeetingController extends Controller { public function index(Request $r):JsonResponse{$items=Meeting::withCount('actionItems')->latest('meeting_date')->paginate($r->integer('per_page',25));return ApiResponse::success($items->items(),null,['current_page'=>$items->currentPage(),'last_page'=>$items->lastPage(),'total'=>$items->total()]);} public function store(Request $r):JsonResponse{$data=$r->validate(['minutes_number'=>['required','string','max:100','unique:meetings,minutes_number'],'meeting_type'=>['required','string','max:255'],'meeting_date'=>['required','date'],'meeting_time'=>['nullable','date_format:H:i'],'location'=>['nullable','string','max:255'],'chairperson'=>['nullable','string','max:255'],'agenda'=>['nullable','string','max:5000'],'discussion_summary'=>['nullable','string','max:5000'],'decisions_summary'=>['nullable','string','max:5000'],'implementation_owner'=>['nullable','string','max:255']]);return ApiResponse::success(Meeting::create($data),'Meeting created.',[],201);} public function show(Meeting $meeting):JsonResponse{return ApiResponse::success($meeting->load('actionItems'));} public function storeAction(Request $r,Meeting $meeting):JsonResponse{$data=$r->validate(['item_type'=>['required',Rule::in(['decision','recommendation','task'])],'description'=>['required','string','max:5000'],'responsible'=>['nullable','string','max:255'],'executing_entity'=>['nullable','string','max:255'],'priority'=>['required',Rule::in(['low','normal','high'])],'due_date'=>['nullable','date'],'notes'=>['nullable','string','max:3000']]);return ApiResponse::success($meeting->actionItems()->create($data),'Meeting action created.',[],201);} }
